function check() {
    var LogUser = workflowData.getMetaDataMap().get("LogUser");
	var empId = workflowData.getMetaDataMap().get("chrsId");
	var requestedBy = workflowData.getMetaDataMap().get("requestedBy");
var Status = workflowData.getMetaDataMap().get("Status");
    log.info("LogUser :" + LogUser);
	log.info("empId :" + empId);
	log.info("requestedBy :" + requestedBy);
    if ((Status == "true") && (requestedBy != empId)) {
        
        return true;
    }
    else {
        return false;
    }
}

